package com.beeboee.magnot.server;import com.beeboee.magnot.region.FerrousRegion;import net.minecraft.core.BlockPos;import net.minecraft.core.particles.ParticleTypes;import net.minecraft.server.level.ServerLevel;import net.minecraft.sounds.*;public final class FerrousEffects{private FerrousEffects(){}public static void firstCorner(ServerLevel l,BlockPos p){l.playSound(null,p,SoundEvents.SLIME_BLOCK_PLACE,SoundSource.BLOCKS,.5f,.85f);l.sendParticles(ParticleTypes.CRIT,p.getX()+.5,p.getY()+.5,p.getZ()+.5,12,.4,.4,.4,0);}public static void confirm(ServerLevel l,BlockPos p,FerrousRegion r){l.playSound(null,p,SoundEvents.SLIME_BLOCK_PLACE,SoundSource.BLOCKS,.5f,.95f);l.sendParticles(ParticleTypes.CRIT,r.bounds().getCenter().x,r.bounds().getCenter().y,r.bounds().getCenter().z,32,1,1,1,0);}public static void remove(ServerLevel l,FerrousRegion r){BlockPos p=new BlockPos(r.bounds().getCenter());l.playSound(null,p,SoundEvents.SLIME_BLOCK_BREAK,SoundSource.BLOCKS,.5f,.75f);l.sendParticles(ParticleTypes.CRIT,p.getX()+.5,p.getY()+.5,p.getZ()+.5,32,1,1,1,0);}}
